/**
 * Drawing the sheets of an issue. A sheet is drawn by its tab, from the
 * drawings of the views placed on it, and those are generated by the views'
 * own tabs; so each sheet is opened in turn with its views, its paper is read
 * as the SVG the export buttons use, and the tabs this opened are closed
 * again and the one the person was on is brought back.
 */

import { sheetDxf } from '@/components/viewer/sheets/sheet-dxf';
import { sheetSvgText } from '@/components/viewer/sheets/sheet-export';
import { activateDocumentTab, openProjectView } from '@/project/open-view';
import { closeDocumentTab, useDocumentTabs } from '@/project/document-tabs';
import { useProjectStore } from '@/project/project-store';
import { useViewDrawings } from '@/project/view-drawings';
import type { ProjectSheet } from '@/project/types';

const WAIT_MS = 120_000;
const SETTLE_MS = 700;
const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

async function until(done: () => boolean, ms = WAIT_MS): Promise<boolean> {
  const end = Date.now() + ms;
  while (!done()) {
    if (Date.now() > end) return false;
    await sleep(100);
  }
  return true;
}

export interface Captured {
  /** Sheet id → its SVG, sized in millimetres. */
  svgs: Map<string, string>;
  /** Sheet id → its DXF, when asked for (it is read from the sheet on screen). */
  dxfs: Map<string, Uint8Array>;
  /** The sheets that could not be drawn. */
  failed: ProjectSheet[];
}

export async function captureSheets(sheets: readonly ProjectSheet[], options: { dxf?: boolean } = {}): Promise<Captured> {
  const before = useDocumentTabs.getState();
  const svgs = new Map<string, string>();
  const dxfs = new Map<string, Uint8Array>();
  const failed: ProjectSheet[] = [];
  try {
    for (const sheet of sheets) {
      const drawn = new Set<string>();
      for (const vp of sheet.viewports ?? []) {
        const view = useProjectStore.getState().views.find((v) => v.id === vp.viewId);
        if (!view || view.kind === '3d') continue;
        openProjectView(view.id);
        drawn.add(view.id);
      }
      const ready = await until(() => [...drawn].every((id) => useViewDrawings.getState().byView[id]?.status === 'ready'));
      activateDocumentTab(sheet.id);
      const found = await until(() => document.querySelector(`svg[data-sheet-id="${CSS.escape(sheet.id)}"]`) !== null, 10_000);
      await sleep(SETTLE_MS);
      const svg = found ? document.querySelector<SVGSVGElement>(`svg[data-sheet-id="${CSS.escape(sheet.id)}"]`) : null;
      if (!ready || !svg) failed.push(sheet);
      else {
        svgs.set(sheet.id, sheetSvgText(svg, sheet));
        if (options.dxf) dxfs.set(sheet.id, sheetDxf(svg, sheet));
      }
    }
  } finally {
    activateDocumentTab(before.activeId);
    for (const id of useDocumentTabs.getState().openIds) if (!before.openIds.includes(id)) closeDocumentTab(id);
  }
  return { svgs, dxfs, failed };
}
